CREATE POLICY "office files own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'office-files' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "office files own write" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'office-files' AND (storage.foldername(name))[1] = auth.uid()::text AND public.has_app_access(auth.uid()));
CREATE POLICY "office files own update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'office-files' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "office files own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'office-files' AND (storage.foldername(name))[1] = auth.uid()::text);